-- Wallet transfer service schema.
--
-- Money is stored as BIGINT in the smallest currency unit (e.g. cents).
-- Floating point is never used for monetary values to avoid rounding errors.
--
-- The schema is written in portable, standard SQL (no database-specific types
-- or functions) so it runs unchanged on PostgreSQL and SQLite. Identifiers are
-- generated by the application instead of relying on database-specific
-- auto-increment syntax, and JSON is stored as TEXT.

CREATE TABLE wallets (
    id          TEXT        PRIMARY KEY,
    balance     BIGINT      NOT NULL DEFAULT 0,
    currency    TEXT        NOT NULL DEFAULT 'USD',
    created_at  TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- A wallet can never go negative. This is the last line of defence
    -- against double spending even if application logic has a bug.
    CONSTRAINT wallets_balance_non_negative CHECK (balance >= 0)
);

CREATE TABLE transfers (
    id              TEXT        PRIMARY KEY,
    from_wallet_id  TEXT        NOT NULL REFERENCES wallets (id),
    to_wallet_id    TEXT        NOT NULL REFERENCES wallets (id),
    amount          BIGINT      NOT NULL,
    status          TEXT        NOT NULL DEFAULT 'PENDING',
    created_at      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT transfers_amount_positive CHECK (amount > 0),
    -- A transfer must move money between two different wallets.
    CONSTRAINT transfers_distinct_wallets CHECK (from_wallet_id <> to_wallet_id),
    -- Only the states defined in the assignment state machine are allowed.
    CONSTRAINT transfers_status_valid CHECK (status IN ('PENDING', 'PROCESSED', 'FAILED'))
);

CREATE INDEX idx_transfers_from_wallet ON transfers (from_wallet_id);
CREATE INDEX idx_transfers_to_wallet   ON transfers (to_wallet_id);

CREATE TABLE ledger_entries (
    -- Application-generated identifier (e.g. UUID) to stay portable across
    -- databases that differ in auto-increment syntax.
    id          TEXT        PRIMARY KEY,
    transfer_id TEXT        NOT NULL REFERENCES transfers (id),
    wallet_id   TEXT        NOT NULL REFERENCES wallets (id),
    type        TEXT        NOT NULL,
    amount      BIGINT      NOT NULL,
    created_at  TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT ledger_amount_positive CHECK (amount > 0),
    CONSTRAINT ledger_type_valid      CHECK (type IN ('DEBIT', 'CREDIT')),

    -- Each transfer produces exactly one DEBIT and one CREDIT. This unique
    -- constraint makes it impossible to record a duplicate side of a transfer,
    -- even under retries or concurrent execution.
    CONSTRAINT ledger_one_entry_per_side UNIQUE (transfer_id, type)
);

CREATE INDEX idx_ledger_wallet   ON ledger_entries (wallet_id);
CREATE INDEX idx_ledger_transfer ON ledger_entries (transfer_id);

CREATE TABLE idempotency_records (
    -- The client-supplied idempotency key is the primary key. The UNIQUE
    -- nature of a primary key is what guarantees exactly-once handling: a
    -- duplicate request fails to insert and we return the stored result.
    idempotency_key TEXT        PRIMARY KEY,

    -- The transfer produced by the original request. The response for a
    -- replayed request is rebuilt from this transfer row, so there is a single
    -- source of truth and no risk of a stale cached copy.
    transfer_id     TEXT        NOT NULL REFERENCES transfers (id),

    -- Hash of the request payload. If the same key arrives with different
    -- parameters it is a client error (key reuse), not a legitimate retry.
    request_hash    TEXT        NOT NULL,

    created_at      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);
